package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"

	"github.com/shopspring/decimal"
)

type LedgerRec struct { // 01 LEDGER-REC, 14 bytes
	BrBranch string          // PIC X(2) @0 len=2
	BrAcct   string          // PIC X(4) @2 len=4
	BrType   string          // PIC X(1) @6 len=1
	BrAmt    decimal.Decimal // PIC 9(5)V99 @7 len=7
}

var WsEofFlag string = "N"        // PIC X len=1 = "N"
var WsFirstFlag string = "Y"      // PIC X len=1 = "Y"
var WsPrevBranch string = "  "    // PIC X(2) len=2 = SPACES
var WsPrevAcct string = "    "    // PIC X(4) len=4 = SPACES
var WsBal decimal.Decimal = decimal.Zero       // PIC S9(7)V99 len=9 = 0
var WsBranchTot decimal.Decimal = decimal.Zero // PIC S9(9)V99 len=11 = 0
var WsGrandTot decimal.Decimal = decimal.Zero  // PIC S9(9)V99 len=11 = 0
var WsSkipped int64 = 0                        // PIC 99 len=2 = 0
var WsAmtEd string                             // PIC ZZ,ZZ9.99 len=9
var WsBalEd string                             // PIC -Z,ZZZ,ZZ9.99 len=13
var WsTotEd string                             // PIC -ZZZ,ZZZ,ZZ9.99 len=15

var ledgerRecords []LedgerRec
var curIdx int
var curRec LedgerRec

func storeDecimal(val decimal.Decimal, intDigits int, scale int) decimal.Decimal {
	truncated := val.Truncate(int32(scale))
	isNeg := truncated.Sign() < 0
	abs := truncated.Abs()
	intPart := abs.Truncate(0)
	frac := abs.Sub(intPart)
	intStr := intPart.StringFixed(0)
	if len(intStr) > intDigits {
		intStr = intStr[len(intStr)-intDigits:]
	}
	newIntPart, err := decimal.NewFromString(intStr)
	if err != nil {
		newIntPart = decimal.Zero
	}
	resultAbs := newIntPart.Add(frac)
	resultAbs = resultAbs.Truncate(int32(scale))
	if isNeg && !resultAbs.IsZero() {
		resultAbs = resultAbs.Neg()
	}
	return resultAbs
}

func formatEdited(v decimal.Decimal, pic string) string {
	hasSign := len(pic) > 0 && (pic[0] == '-' || pic[0] == '+')
	bodyPic := pic
	signChar := ' '
	if hasSign {
		bodyPic = pic[1:]
		if v.Sign() < 0 && !v.IsZero() {
			signChar = '-'
		} else {
			if pic[0] == '+' {
				signChar = '+'
			} else {
				signChar = ' '
			}
		}
	}
	dotIdx := strings.Index(bodyPic, ".")
	decSlots := 0
	if dotIdx != -1 {
		for _, ch := range bodyPic[dotIdx+1:] {
			if ch == 'Z' || ch == '9' {
				decSlots++
			}
		}
	}
	abs := v.Abs()
	truncated := abs.Truncate(int32(decSlots))
	intPart := truncated.Truncate(0)
	intStr := intPart.StringFixed(0)

	intPicPart := bodyPic
	if dotIdx != -1 {
		intPicPart = bodyPic[:dotIdx]
	}
	intSlots := 0
	for _, ch := range intPicPart {
		if ch == 'Z' || ch == '9' {
			intSlots++
		}
	}
	if len(intStr) > intSlots {
		intStr = intStr[len(intStr)-intSlots:]
	}
	fracStr := ""
	if decSlots > 0 {
		fixed := truncated.StringFixed(int32(decSlots))
		parts := strings.Split(fixed, ".")
		if len(parts) == 2 {
			fracStr = parts[1]
			if len(fracStr) < decSlots {
				fracStr = fracStr + strings.Repeat("0", decSlots-len(fracStr))
			} else if len(fracStr) > decSlots {
				fracStr = fracStr[:decSlots]
			}
		} else {
			fracStr = strings.Repeat("0", decSlots)
		}
	}
	bodyOut := make([]rune, len(bodyPic))
	intIdx := len(intStr) - 1
	fracIdx := len(fracStr) - 1
	for i := len(bodyPic) - 1; i >= 0; i-- {
		ch := bodyPic[i]
		if ch == '.' {
			bodyOut[i] = '.'
		} else if ch == ',' {
			bodyOut[i] = ','
		} else if ch == 'Z' || ch == '9' {
			isDec := false
			if dotIdx != -1 && i > dotIdx {
				isDec = true
			}
			if isDec {
				var d rune
				if fracIdx >= 0 {
					d = rune(fracStr[fracIdx])
					fracIdx--
				} else {
					d = '0'
				}
				bodyOut[i] = d
			} else {
				var d rune
				if intIdx >= 0 {
					d = rune(intStr[intIdx])
					intIdx--
				} else {
					d = '0'
				}
				bodyOut[i] = d
			}
		} else {
			bodyOut[i] = rune(ch)
		}
	}
	suppressed := true
	for i := 0; i < len(bodyPic); i++ {
		if dotIdx != -1 && i > dotIdx {
			break
		}
		picCh := rune(bodyPic[i])
		if picCh == ',' {
			if suppressed {
				bodyOut[i] = ' '
			} else {
				bodyOut[i] = ','
			}
		} else if picCh == 'Z' {
			digit := bodyOut[i]
			if suppressed && digit == '0' {
				bodyOut[i] = ' '
			} else {
				suppressed = false
			}
		} else if picCh == '9' {
			suppressed = false
		} else if picCh == '.' {
			suppressed = false
		}
	}
	if hasSign {
		return string(signChar) + string(bodyOut)
	}
	return string(bodyOut)
}

func loadLedgerFile() {
	f, err := os.Open("input.dat")
	if err != nil {
		if os.IsNotExist(err) {
			ledgerRecords = []LedgerRec{}
			curIdx = 0
			return
		}
		fmt.Fprintf(os.Stderr, "open input.dat: %v\n", err)
		os.Exit(1)
	}
	defer f.Close()
	scanner := bufio.NewScanner(f)
	const maxCap = 1024 * 1024
	buf := make([]byte, 0, 64*1024)
	scanner.Buffer(buf, maxCap)
	ledgerRecords = []LedgerRec{}
	for scanner.Scan() {
		line := scanner.Text()
		if len(line) < 14 {
			line = line + strings.Repeat(" ", 14-len(line))
		} else if len(line) > 14 {
			line = line[:14]
		}
		brBranch := line[0:2]
		brAcct := line[2:6]
		brType := line[6:7]
		brAmtRaw := line[7:14]
		var sb strings.Builder
		for i := 0; i < len(brAmtRaw); i++ {
			c := brAmtRaw[i]
			if c >= '0' && c <= '9' {
				sb.WriteByte(c)
			} else {
				sb.WriteByte('0')
			}
		}
		digits := sb.String()
		var amt decimal.Decimal
		if digits != "" {
			n, err := strconv.ParseInt(digits, 10, 64)
			if err != nil {
				n = 0
			}
			amt = decimal.New(n, -2)
		} else {
			amt = decimal.Zero
		}
		ledgerRecords = append(ledgerRecords, LedgerRec{
			BrBranch: brBranch,
			BrAcct:   brAcct,
			BrType:   brType,
			BrAmt:    amt,
		})
	}
	if err := scanner.Err(); err != nil {
		fmt.Fprintf(os.Stderr, "read input.dat: %v\n", err)
		os.Exit(1)
	}
	curIdx = 0
}

func MainPara() {
	loadLedgerFile()
	ReadPara()
	for WsEofFlag != "Y" {
		ProcessPara()
	}
	if WsFirstFlag != "Y" {
		AcctBreakPara()
		BranchBreakPara()
	}
	GrandPara()
}

func ReadPara() {
	if curIdx >= len(ledgerRecords) {
		WsEofFlag = "Y"
		return
	}
	curRec = ledgerRecords[curIdx]
	curIdx++
	WsEofFlag = "N"
}

func ProcessPara() {
	if WsFirstFlag == "Y" {
		WsPrevBranch = curRec.BrBranch
		WsPrevAcct = curRec.BrAcct
		WsFirstFlag = "N"
	} else {
		if curRec.BrBranch != WsPrevBranch {
			AcctBreakPara()
			BranchBreakPara()
			WsPrevBranch = curRec.BrBranch
			WsPrevAcct = curRec.BrAcct
		} else {
			if curRec.BrAcct != WsPrevAcct {
				AcctBreakPara()
				WsPrevAcct = curRec.BrAcct
			}
		}
	}
	PostPara()
	ReadPara()
}

func PostPara() {
	WsAmtEd = formatEdited(curRec.BrAmt, "ZZ,ZZ9.99")
	switch curRec.BrType {
	case "D":
		WsBal = storeDecimal(WsBal.Add(curRec.BrAmt), 7, 2)
		fmt.Printf("%s D %s\n", curRec.BrAcct, WsAmtEd)
	case "C":
		WsBal = storeDecimal(WsBal.Sub(curRec.BrAmt), 7, 2)
		fmt.Printf("%s C %s\n", curRec.BrAcct, WsAmtEd)
	default:
		WsSkipped = (WsSkipped + 1) % 100
		fmt.Printf("%s ? SKIPPED\n", curRec.BrAcct)
	}
}

func AcctBreakPara() {
	WsBalEd = formatEdited(WsBal, "-Z,ZZZ,ZZ9.99")
	fmt.Printf("  ACCOUNT %s BALANCE:%s\n", WsPrevAcct, WsBalEd)
	WsBranchTot = storeDecimal(WsBranchTot.Add(WsBal), 9, 2)
	WsBal = storeDecimal(decimal.Zero, 7, 2)
}

func BranchBreakPara() {
	WsTotEd = formatEdited(WsBranchTot, "-ZZZ,ZZZ,ZZ9.99")
	fmt.Printf(" BRANCH %s TOTAL:%s\n", WsPrevBranch, WsTotEd)
	WsGrandTot = storeDecimal(WsGrandTot.Add(WsBranchTot), 9, 2)
	WsBranchTot = storeDecimal(decimal.Zero, 9, 2)
}

func GrandPara() {
	WsTotEd = formatEdited(WsGrandTot, "-ZZZ,ZZZ,ZZ9.99")
	fmt.Printf("GRAND TOTAL:%s\n", WsTotEd)
	fmt.Printf("SKIPPED: %02d\n", WsSkipped)
}

func main() {
	MainPara()
}
